"use client";

import Link from "next/link";
import { AddToPlan } from "../SavedSuppliers";
import { useSearchParams } from "next/navigation";
import { Suspense, useEffect, useState } from "react";
import { supabase } from "../supabase";

type Vendor = { id:string; business_name:string; category:string; description:string; phone:string; email:string; website:string; town:string; coverage_areas:string; services:string; };

function VendorProfileContent(){
 const searchParams=useSearchParams(); const name=searchParams.get("name")||""; const [vendor,setVendor]=useState<Vendor|null>(null); const [loading,setLoading]=useState(true); const [error,setError]=useState("");
 useEffect(()=>{async function loadVendor(){if(!name){setError("Vendor not found.");setLoading(false);return}const {data,error:vendorError}=await supabase.from("vendor_profiles").select("id,business_name,category,description,phone,email,website,town,coverage_areas,services").eq("business_name",name).limit(1).maybeSingle();if(vendorError||!data){const {data:override,error:overrideError}=await supabase.from("vendor_listing_overrides").select("external_id,business_name,category,description,phone,email,website,town,coverage_areas,services").eq("business_name",name).limit(1).maybeSingle();if(overrideError||!override){setError("We couldn't find this vendor profile.");setLoading(false);return}setVendor({id:override.external_id,business_name:override.business_name||name,category:override.category||"Other",description:override.description||"",phone:override.phone||"",email:override.email||"",website:override.website||"",town:override.town||"",coverage_areas:override.coverage_areas||"",services:override.services||""});setLoading(false);return}setVendor(data as Vendor);setLoading(false)}void loadVendor()},[name]);
 return <main className="min-h-screen bg-[#f8f4ec] px-5 py-8 text-slate-900 sm:px-6 sm:py-10"><div className="mx-auto max-w-5xl"><header className="mb-8 flex items-center justify-between gap-4"><Link href="/" className="text-2xl font-extrabold tracking-tight"><span className="text-orange-500">Just</span><span className="text-[#063d39]">Celebrate</span></Link><Link href="/#vendors" className="rounded-xl border border-[#ddd5c8] bg-white px-4 py-2.5 text-sm font-bold text-[#063d39]">← Vendors</Link></header>{loading?<div className="rounded-3xl border border-[#e5ded1] bg-white p-8">Loading vendor…</div>:null}{error?<div className="rounded-3xl border border-[#e5ded1] bg-white p-8 text-slate-600">{error}</div>:null}{vendor?<article className="overflow-hidden rounded-[2rem] border border-[#e5ded1] bg-white shadow-sm"><div className="bg-[#063d39] px-6 py-9 text-white sm:px-10 sm:py-12"><span className="inline-flex rounded-full bg-white/10 px-3 py-1 text-xs font-bold uppercase tracking-wider text-orange-200">{vendor.category}</span><h1 className="mt-4 max-w-3xl text-4xl font-extrabold tracking-tight sm:text-5xl">{vendor.business_name}</h1>{vendor.town?<p className="mt-3 text-lg text-white/75">📍 {vendor.town}</p>:null}</div><div className="p-6 sm:p-10">{vendor.description?<p className="max-w-3xl text-base leading-7 text-slate-600">{vendor.description}</p>:null}<div className="mt-8 grid gap-4 sm:grid-cols-2">{vendor.services?<section className="rounded-2xl bg-[#f8f4ec] p-5"><p className="text-xs font-bold uppercase tracking-[0.18em] text-orange-500">What they offer</p><h2 className="mt-2 text-lg font-extrabold text-[#063d39]">Services</h2><p className="mt-2 text-sm leading-6 text-slate-600">{vendor.services}</p></section>:null}{vendor.coverage_areas?<section className="rounded-2xl bg-[#f8f4ec] p-5"><p className="text-xs font-bold uppercase tracking-[0.18em] text-orange-500">Where they work</p><h2 className="mt-2 text-lg font-extrabold text-[#063d39]">Areas covered</h2><p className="mt-2 text-sm leading-6 text-slate-600">{vendor.coverage_areas}</p></section>:null}</div><div className="mt-8 rounded-2xl border border-[#d9e4df] bg-white p-5"><p className="text-xs font-bold uppercase tracking-[0.18em] text-orange-500">Your celebration</p><h2 className="mt-2 text-xl font-extrabold text-[#063d39]">Like this vendor?</h2><p className="mt-1 text-sm text-slate-600">Save them straight to My Planning Portal so you don’t have to search again.</p><AddToPlan vendor={vendor}/></div><div className="mt-5 grid gap-3 sm:grid-cols-2">{vendor.email?<a href={`mailto:${vendor.email}`} className="rounded-xl bg-orange-500 px-5 py-3.5 text-center font-bold text-white">Send enquiry →</a>:null}{vendor.website?<a href={vendor.website} target="_blank" rel="noreferrer" className="rounded-xl bg-[#063d39] px-5 py-3.5 text-center font-bold text-white">Visit website</a>:null}{vendor.phone?<a href={`tel:${vendor.phone.replace(/\s/g,"")}`} className="rounded-xl border border-[#ddd5c8] px-5 py-3.5 text-center font-bold text-[#063d39]">Call vendor</a>:null}<Link href="/planner#suppliers" className="rounded-xl border border-[#ddd5c8] px-5 py-3.5 text-center font-bold text-[#063d39]">Back to my plan</Link></div><div className="mt-10 border-t border-[#eee7dc] pt-7"><p className="text-sm font-bold text-[#063d39]">Is this your business?</p><p className="mt-1 text-sm text-slate-500">Manage your details and enquiries by claiming your listing.</p><Link href={`/claim-business?business=${encodeURIComponent(vendor.business_name)}&vendor=${encodeURIComponent(vendor.id)}`} className="mt-3 inline-flex text-sm font-bold text-orange-600 underline underline-offset-4">Claim this listing</Link></div></div></article>:null}</div></main>;
}
export default function VendorProfilePage(){return <Suspense fallback={<main className="min-h-screen bg-[#f8f4ec] p-10">Loading vendor…</main>}><VendorProfileContent/></Suspense>}
